Layout.Stylesheet:
:root { --main: green; --frame: 1pt solid green }
/* red as long as no var() applies */
html p.root, html p.fallback, html p.st { color: red }
html li span { color: red }
html p.root { color: var(--main) }
html div.over { --main: blue }
html p.fallback { color: var(--undefined, green) }
html p.drop { color: green }
html p.drop { color: var(--undefined) }
html p.border { border: var(--frame); padding: var(--pad, 2pt) }
html p.mark::before { --mark: "» "; content: var(--mark); color: var(--main) }
html li { --main: red }
html ul.list li { --main: green }
html li span { color: var(--main) }
